#!/usr/bin/env python3
"""Apply script: fix scorecard 500 caused by NULL nationality-zone multipliers.

Run from the HealthCross repo root: python3 apply_scorecard_null_multiplier_fix.py
IMPORTANT: after applying, RESTART the server (./start_healthcross.sh) so the
migration backfill actually runs against your real database before scoring again.
"""
import base64, hashlib, os, sys

MARKER = "SCORECARD_NULL_MULTIPLIER_FIX_2026_08_05"

FILES = [
    {
        'path': 'app/db_migrate.py',
        'sha256': '099406d4e57a7e193bdab22054435acad44bb3857581b363ad7cd8f0b9b657be',
        'size': 3662,
        'b64': '',
    },
    {
        'path': 'app/scoring/rules/demographic.py',
        'sha256': 'abe097c195837f4d558f9d2e732de611036f7e080d6f4d54de991268746c536c',
        'size': 10385,
        'b64': '',
    },
    {
        'path': 'tests/test_db_migrate.py',
        'sha256': '53b5f77c64afe50a0d0c4001ad76f64765f4ece7d5f4a534967e9f35e2964993',
        'size': 3104,
        'b64': '',
    },
    {
        'path': 'tests/test_scoring_demographic.py',
        'sha256': '843909fceb0a9d2e4f7db99939b6af7c565b132e753ef532d1a0061caaa622d0',
        'size': 8896,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 482 passed)")
        print("Then RESTART the server (./start_healthcross.sh) so the migration backfill runs against your real DB.")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
